1: /* ==========================================================================
2:    Phase E3 weather surfaces, the --wx- token namespace
3:    (docs/research.md palette table, "New tokens live in a --wx- namespace
4:    next to --rp and --rv so the report and Money River files never change").
5: 
6:    The seven state tokens, one per weather state in canonical order:
7: 
8:      wx-clear     #56B4E9   sky blue (Okabe-Ito), calm and no shortfall
9:      wx-cloudy    #46617c   cloud slate, long runway with a spending gap
10:      wx-overcast  #2f4257   deep slate, the darker sibling of cloudy
11:      wx-rain      #2f7f7c   water lit, spending driven 3.0 to 11.9 months
12:      wx-drought   #d97b3f   drought orange, income covers 65 percent or less
13:      wx-storm     #ff6a4d   storm vermillion, runway under 3.0 months
14:      wx-flood     #10333f   water deep, buffer depleted or runway at 0.0
15: 
16:    Plus the two grounds every surface sits on: wx-grounds #070c18 (the
17:    archival navy, same value as --rp-void but read from its own token so
18:    this file never depends on --rp-) and wx-parchment #e9e0c9 for text.
19: 
20:    Soft tints (each state color at 26 percent over wx-grounds) carry every
21:    printed label, so measured contrast for parchment text stays above
22:    WCAG AA on all seven cells (worst case 9.3 to 1 on wx-clear-soft).
23:    Solid state colors are used for tile fills, swatches, and rules only,
24:    where no small text sits on them.
25: 
26:    The E3 strip slots do not use these state colors: they read the five
27:    verdict bands through their tailwind class and currentColor (see the
28:    .wx-slot rule below), so the badge and the strip share one source of
29:    band color.
30: 
31:    Motion in this file is gated behind prefers-reduced-motion:
32:    no-preference, matching src/index.css, which also zeroes animation
33:    durations globally under prefers-reduced-motion: reduce.
34:    ========================================================================== */
35: 
36: :root {
37:   /* The seven state colors. */
38:   --wx-clear: #56b4e9;
39:   --wx-cloudy: #46617c;
40:   --wx-overcast: #2f4257;
41:   --wx-rain: #2f7f7c;
42:   --wx-drought: #d97b3f;
43:   --wx-storm: #ff6a4d;
44:   --wx-flood: #10333f;
45: 
46:   /* Grounds and text. */
47:   --wx-grounds: #070c18;
48:   --wx-parchment: #e9e0c9;
49:   --wx-rule: rgba(233, 224, 201, 0.24);
50:   --wx-text-dim: rgba(233, 224, 201, 0.74);
51:   --wx-text-faint: rgba(233, 224, 201, 0.54);
52: 
53:   /* Soft tints for any surface that prints text on a state color. */
54:   --wx-clear-soft: #1c384e;
55:   --wx-cloudy-soft: #172232;
56:   --wx-overcast-soft: #111a28;
57:   --wx-rain-soft: #112a32;
58:   --wx-drought-soft: #3e2922;
59:   --wx-storm-soft: #482426;
60:   --wx-flood-soft: #091622;
61: 
62:   /* Utility, deliberately local so nothing here reaches into --rp-. */
63:   --wx-font-display: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas,
64:     "Liberation Mono", monospace;
65:   --wx-font-body: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
66:   --wx-radius: 4px;
67: }
68: 
69: /* ==========================================================================
70:    Forecast strip: 12 month tiles, one per weather state
71:    ========================================================================== */
72: 
73: .wx-strip {
74:   display: block;
75:   width: 100%;
76: }
77: 
78: .wx-strip__svg {
79:   display: block;
80:   width: 100%;
81:   height: auto;
82: }
83: 
84: /* Band colored month slots: the verdict band's own tailwind class sets
85:    the color, fill picks it up through currentColor, and the 22 percent
86:    tint keeps the glyph and the curve legible on top. One source of
87:    band color for the badge and the strip (tailwind.config.js cp). */
88: .wx-slot {
89:   fill: currentColor;
90:   fill-opacity: 0.22;
91: }
92: 
93: .wx-strip__glyph {
94:   fill: currentColor;
95:   font-family: var(--wx-font-body);
96:   font-size: 13px;
97: }
98: 
99: .wx-strip__month {
100:   fill: var(--wx-parchment);
101:   font-family: var(--wx-font-display);
102:   font-size: 9.5px;
103:   letter-spacing: 0.06em;
104: }
105: 
106: .wx-strip__horizon {
107:   fill: var(--wx-text-faint);
108:   font-family: var(--wx-font-display);
109:   font-size: 10px;
110:   letter-spacing: 0.06em;
111: }
112: 
113: .wx-strip__empty {
114:   fill: var(--wx-parchment);
115:   font-family: var(--wx-font-display);
116:   font-size: 11px;
117: }
118: 
119: .wx-strip__placeholder {
120:   fill: none;
121:   stroke: var(--wx-rule);
122:   stroke-dasharray: 4 4;
123: }
124: 
125: /* Curve, grounds, and front ---------------------------------------------- */
126: 
127: .wx-zero-line {
128:   stroke: var(--wx-rule);
129:   stroke-width: 1;
130:   stroke-dasharray: 3 5;
131: }
132: 
133: .wx-history-line {
134:   fill: none;
135:   stroke: var(--wx-text-faint);
136:   stroke-width: 1.5;
137: }
138: 
139: .wx-history-dot {
140:   fill: var(--wx-text-faint);
141: }
142: 
143: .wx-history-legend {
144:   fill: var(--wx-text-faint);
145:   font-family: var(--wx-font-display);
146:   font-size: 9.5px;
147:   letter-spacing: 0.08em;
148: }
149: 
150: .wx-projection-line {
151:   fill: none;
152:   stroke: var(--wx-parchment);
153:   stroke-width: 2.5;
154:   stroke-linecap: round;
155:   stroke-linejoin: round;
156: }
157: 
158: /* The worst case continuation: dashed storm color so it never reads
159:    as the answer key figure on the solid projection line. */
160: .wx-continuation-line {
161:   fill: none;
162:   stroke: var(--wx-storm);
163:   stroke-width: 2;
164:   stroke-dasharray: 7 5;
165:   stroke-linecap: round;
166: }
167: 
168: .wx-front {
169:   stroke-width: 2;
170: }
171: 
172: .wx-front-active {
173:   stroke: var(--wx-storm);
174:   stroke-width: 2.5;
175: }
176: 
177: .wx-front-idle {
178:   stroke: var(--wx-rule);
179:   stroke-dasharray: 4 4;
180: }
181: 
182: /* Pins ------------------------------------------------------------------- */
183: 
184: .wx-pin-stem {
185:   stroke: var(--wx-parchment);
186:   stroke-width: 1.5;
187:   stroke-dasharray: 3 3;
188: }
189: 
190: .wx-pin-dot {
191:   fill: currentColor;
192:   stroke: var(--wx-grounds);
193:   stroke-width: 1.5;
194: }
195: 
196: .wx-pin__label {
197:   fill: var(--wx-parchment);
198:   font-family: var(--wx-font-display);
199:   font-size: 11px;
200:   font-weight: 700;
201:   letter-spacing: 0.04em;
202:   paint-order: stroke;
203:   stroke: var(--wx-grounds);
204:   stroke-width: 3px;
205:   stroke-linejoin: round;
206: }
207: 
208: .wx-pin__label-faint {
209:   fill: var(--wx-text-faint);
210:   font-size: 10px;
211:   font-weight: 400;
212: }
213: 
214: .wx-ei-pin {
215:   fill: var(--wx-storm);
216:   stroke: var(--wx-grounds);
217:   stroke-width: 1.5;
218: }
219: 
220: /* ==========================================================================
221:    Condition bands: the sky legend with the printed threshold sentence.
222:    One band vocabulary (src/lib/verdict.ts): the band's tailwind class on
223:    the list item sets the color, currentColor carries it into the left
224:    rule and the label, and the responsive grid keeps five bands readable
225:    from a phone up to a judging table.
226:    ========================================================================== */
227: 
228: .wx-bands {
229:   display: grid;
230:   grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
231:   gap: 6px;
232:   list-style: none;
233:   margin: 0;
234:   padding: 0;
235: }
236: 
237: .wx-band {
238:   display: flex;
239:   align-items: baseline;
240:   gap: 10px;
241:   padding: 8px 12px;
242:   background: rgba(233, 224, 201, 0.05);
243:   border: 1px solid var(--wx-rule);
244:   border-left: 6px solid currentColor;
245:   border-radius: var(--wx-radius);
246:   min-height: 44px;
247: }
248: 
249: .wx-band-active {
250:   box-shadow: inset 0 0 0 2px var(--wx-parchment);
251: }
252: 
253: .wx-band__glyph {
254:   font-size: 1rem;
255:   color: var(--wx-parchment);
256: }
257: 
258: .wx-band__body {
259:   display: flex;
260:   flex-wrap: wrap;
261:   align-items: baseline;
262:   gap: 2px 12px;
263:   min-width: 0;
264: }
265: 
266: .wx-band__label {
267:   font-family: var(--wx-font-display);
268:   font-size: 0.8125rem;
269:   letter-spacing: 0.08em;
270:   text-transform: uppercase;
271:   color: currentColor;
272: }
273: 
274: .wx-band__threshold {
275:   font-family: var(--wx-font-body);
276:   font-size: 0.8125rem;
277:   color: var(--wx-text-dim);
278: }
279: 
280: /* ==========================================================================
281:    EI cliff overlay: a marker line that sits over the forecast strip, plus
282:    a dotted second line for the worst case pin. The wiring view wraps the
283:    strip and this overlay in .wx-cliff-wrap, which is the positioning
284:    context; the overlay's own .wx-cliff-set fills that box and the lines
285:     position against it with the slot percent the strip's stripLayout
286:     shares, so the marker lands on the same x the curve uses.
287:    ========================================================================== */
288: 
289: .wx-cliff-wrap {
290:   position: relative;
291: }
292: 
293: .wx-cliff-set {
294:   position: absolute;
295:   inset: 0;
296:   pointer-events: none;
297:   z-index: 2;
298: }
299: 
300: .wx-cliff {
301:   position: absolute;
302:   top: 0;
303:   bottom: 0;
304:   width: 0;
305:   border-left: 2px dashed var(--wx-storm);
306: }
307: 
308: /* The worst case continuation line: dotted and dimmer, so it never
309:    reads as the answer key marker or the solid projection curve. */
310: .wx-cliff-after {
311:   border-left-style: dotted;
312:   opacity: 0.7;
313: }
314: 
315: .wx-cliff__label {
316:   position: absolute;
317:   top: 3px;
318:   left: 0;
319:   white-space: nowrap;
320:   padding: 1px 6px;
321:   border-radius: 2px;
322:   background: var(--wx-storm);
323:   color: var(--wx-grounds);
324:   font-family: var(--wx-font-display);
325:   font-size: 0.625rem;
326:   font-weight: 700;
327:   letter-spacing: 0.1em;
328:   text-transform: uppercase;
329: }
330: 
331: /* On a phone the label is wider than the gap to the strip edge, so it
332:    wraps instead of overflowing the panel. */
333: @media (max-width: 40rem) {
334:   .wx-cliff__label {
335:     white-space: normal;
336:     max-width: 62vw;
337:   }
338: }
339: 
340: /* ==========================================================================
341:    Weather panel: the full width section that composes the strip, the
342:    cliff overlay, the honesty note, and the band key. Local spacing only,
343:    nothing here reaches into the cp or rp namespaces beyond the panel
344:    classes the console already defines.
345:    ========================================================================== */
346: 
347: .wx-panel {
348:   display: flex;
349:   flex-direction: column;
350:   gap: 12px;
351: }
352: 
353: .wx-storm-tag {
354:   display: inline-block;
355:   margin-right: 8px;
356:   padding: 1px 6px;
357:   border: 1px solid var(--wx-storm);
358:   border-radius: 2px;
359:   font-family: var(--wx-font-display);
360:   font-size: 0.625rem;
361:   font-weight: 700;
362:   letter-spacing: 0.1em;
363:   text-transform: uppercase;
364:   color: var(--wx-storm);
365:   vertical-align: 1px;
366: }
367: 
368: .wx-honesty {
369:   display: flex;
370:   flex-wrap: wrap;
371:   align-items: baseline;
372:   gap: 4px 10px;
373:   margin: 0;
374:   font-family: var(--wx-font-body);
375:   font-size: 0.8125rem;
376:   line-height: 1.5;
377:   color: var(--wx-text-dim);
378: }
379: 
380: .wx-honesty__swatch {
381:   align-self: center;
382:   width: 22px;
383:   height: 0;
384:   border-top: 2px solid var(--wx-text-faint);
385: }
386: 
387: .wx-honesty__legend {
388:   font-family: var(--wx-font-display);
389:   font-size: 0.6875rem;
390:   letter-spacing: 0.08em;
391:   text-transform: uppercase;
392:   color: var(--wx-text-faint);
393: }
394: 
395: .wx-bands__title {
396:   margin: 4px 0 0;
397: }
398: 
399: /* ==========================================================================
400:    Motion: strip tiles settle in, the cliff line draws down. Only when
401:    motion is welcome; the global prefers-reduced-motion: reduce block in
402:    src/index.css zeroes every animation duration as well.
403:    ========================================================================== */
404: 
405: @media (prefers-reduced-motion: no-preference) {
406:   .wx-strip__tile {
407:     animation: wx-fade 380ms ease-out backwards;
408:     /* The per tile stagger arrives as an inline animation-delay from
409:        ForecastStrip, which wins over this class shorthand. */
410:   }
411: 
412:   .wx-cliff {
413:     animation: wx-fade 480ms ease-out backwards;
414:   }
415: }
416: 
417: @keyframes wx-fade {
418:   from {
419:     opacity: 0;
420:   }
421: 
422:   to {
423:     opacity: 1;
424:   }
425: }

