280: /* ==========================================================================
281:    EI cliff overlay: a marker line that sits over the forecast strip, plus
282:    a dotted second line for the worst case pin. The wiring view wraps the
283:    strip and this overlay in .wx-cliff-wrap, which is the positioning
284:    context; the overlay's own .wx-cliff-set fills that box and the lines
285:     position against it with the slot percent the strip's stripLayout
286:     shares, so the marker lands on the same x the curve uses.
287:    ========================================================================== */
288: 
289: .wx-cliff-wrap {
290:   position: relative;
291: }
292: 
293: .wx-cliff-set {
294:   position: absolute;
295:   inset: 0;
296:   pointer-events: none;
297:   z-index: 2;
298: }
