49:   gap: 6px;
50:   list-style: none;
51:   margin: 0;
52:   padding: 0;
53: }
54: 
55: .jg-shortcut {
56:   display: inline-flex;
57:   align-items: center;
58:   gap: 8px;
59:   min-height: 44px;
60:   padding: 4px 10px;
61:   color: var(--jg-parchment);
62:   background: transparent;
63:   border: 1px solid var(--jg-rule);
64:   border-radius: 4px;
65:   font-family: inherit;
66:   font-size: 0.75rem;
67:   letter-spacing: 0.04em;
68: }
69: 
