172: }
173: 
174: .jg-receipt__mark {
175:   font-weight: 700;
176: }
177: 
178: .jg-receipt__label {
179:   color: rgba(233, 224, 201, 0.54);
180:   font-size: 0.6875rem;
181: }
182: 
183: /* Motion: the active keycap breathes once per state change. Only when
184:    motion is welcome; the global prefers-reduced-motion: reduce block in
185:    src/index.css also zeroes every animation duration. */
186: 
187: @media (prefers-reduced-motion: no-preference) {
