.jg-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px 18px;
  padding: 10px 14px;
  background: var(--jg-panel);
  border-top: 1px solid rgba(233, 224, 201, 0.24);
  font-family: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas,
