export function useJudgeShortcuts(dispatch?: JudgeDispatcher): void {
  const ownDispatcher = useJudgeDispatcher()
  const dispatchAction = dispatch ?? ownDispatcher
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.isComposing || event.repeat) return
      const target = event.target
      const inTextEntry = isTextEntry(target)
      const state = useConsole.getState()
      const typedGateOpen = state.typedStatus === 'reading' || state.typedStatus === 'pending'
      const action = resolveJudgeKey(event, { inTextEntry, typedGateOpen })
      if (!action) return
      if (action.kind === 'focus_lookup') event.preventDefault()
      dispatchAction(action)
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [dispatchAction])
}
