import { readFileSync } from 'node:fs'
import { createElement } from 'react'
import { renderToString } from 'react-dom/server'
import { afterEach, describe, expect, it } from 'vitest'
import { parseProfilesArtifact, type ProfilesArtifact } from '../../data/profiles'
import { useConsole } from '../../state/consoleStore'
import GuardChips from './GuardChips'

/**
 * Guard chip row contract (Phase E6): nothing renders before boot or
 * with a clean account, and a flagged account prints one short chip per
 * flag with the full guard sentence behind it for hover and for screen
 * readers. The row is prop free, so the store is the only input.
 */

const ARTIFACT: ProfilesArtifact = parseProfilesArtifact(
  JSON.parse(readFileSync(new URL('../../../public/data/engine/profiles.json', import.meta.url), 'utf8')),
)

afterEach(() => {
  useConsole.setState({
    status: 'idle',
    error: null,
    bundle: null,
    query: '',
    selectedId: null,
  })
})

describe('GuardChips', () => {
  it('renders nothing before boot and with nothing selected', () => {
    expect(renderToString(createElement(GuardChips))).toBe('')
    useConsole.setState({ status: 'ready', bundle: ARTIFACT, selectedId: null })
    expect(renderToString(createElement(GuardChips))).toBe('')
  })

  it('renders nothing for a clean account', () => {
    useConsole.setState({
      status: 'ready',
      bundle: ARTIFACT,
      selectedId: '68257',
      twist: { jobLoss: false, incomeFactor: 1, billsDeltaPct: 0, oneOffMonthsTenths: 0, durationMonths: 0 },
    })
    const html = renderToString(createElement(GuardChips))
    expect(html).toBe('')
  })

  it('prints one short chip per flag with the full message behind it', () => {
    useConsole.setState({ status: 'ready', bundle: ARTIFACT, selectedId: '42988' })
    const html = renderToString(createElement(GuardChips))
    expect(html).toContain('aria-label="Edge guard flags"')
    expect(html).toContain('jg-chip')
    expect(html).toContain('negative buffer')
    expect(html).toContain('defaulted loan')
    expect(html).toContain('Savings buffer is below zero: the baseline already reads 0.0 months of runway')
    expect(html).toContain('Loan in arrears (status D): the account still pays a loan it is behind on.')
    expect(html).toContain('jg-sr')
    expect(html).toContain('title="')
  })
})

